#!/usr/bin/env python3\n\"\"\"\nScript to find duplicate packages in pnpm-lock.yaml\n\nThe pnpm-lock.yaml file has this structure:\npackage-name:\n specifier: ^x.y.z\n version: a.b.c\n\nWe need to detect if the same package appears multiple times in the file.\n\"\"\"\n\nimport re\nfrom collections import defaultdict\n\ndef find_duplicate_packages(filepath='pnpm-lock.yaml'):\n    \"\"\"Find duplicate packages in pnpm-lock.yaml\"\"\"\n    \n    with open(filepath, 'r') as f:\n        lines = f.readlines()\n\n    # Pattern to match package names in pnpm-lock.yaml format:\n    # Package lines have format: \"package-name:\" or \"package-name@x.y.z:\"\n    # Section headers have format: \"section-name:\" (dependencies, devDependencies, overrides, etc.)\n    \n    # This pattern matches package names that are at the start of a line and followed by colon\n    package_pattern = re.compile(r'^([a-zA-Z0-9@/\\-_\\.]+):\\s*$')\n\n    duplicates = defaultdict(list)\n\n    for line_num, line in enumerate(lines, 1):\n        line = line.rstrip()\n\n        # Skip empty lines and known section headers\n        if not line or line in ['dependencies:', 'devDependencies:', 'overrides:', 'settings:', 'importers:', 'lockfileVersion:']:\n            continue\n\n        # Check if this is a package name line (standalone lines with colon)\n        match = package_pattern.match(line)\n        if match:\n            # Extract package name (first token before colon)\n            package_name = match.group(1)\n\n            # Add to duplicates tracking\n            duplicates[package_name].append({\n                'line': line_num,\n                'content': line\n            })\n\n    # Filter to only show actual duplicates (more than one occurrence)\n    actual_duplicates = {pkg: occurrences for pkg, occurrences in duplicates.items() if len(occurrences) > 1}\n\n    return actual_duplicates\n\ndef main():\n    print(\"=\" * 80)\n    print(\"Finding duplicate packages in pnpm-lock.yaml\")\n    print(\"=\" * 80)\n    \n    duplicates = find_duplicate_packages()\n    \n    if duplicates:\n        print(f\"\\n❌ Found {len(duplicates)} duplicate packages:\\n\")\n    \n        for package_name, occurrences in sorted(duplicates.items()):\n            print(f\"📦 Package: {package_name}\")\n            print(f\" Occurrences: {len(occurrences)}\")\n            for occ in occurrences:\n                print(f\" - Line {occ['line']}: {occ['content']}\")\n            print()\n    \n        print(f\"\\n📊 Summary: {len(duplicates)} duplicate packages found\")\n        return 1\n    else:\n        print(\"✅ No duplicate packages found!\")\n        print(\"\\nAll packages in pnpm-lock.yaml are unique.\")\n        return 0\n\nif __name__ == \"__main__\":\n    exit(main())\n
